  "elements": [
    {
      "description": "Вызов функции ReadSample является триггером для выполнения последующей логики.",
      "source_ids": ["F001", "F002"],
      "type": "условие"
    },
    {
      "description": "Режим функционирования компонента STANDBY.",
      "source_ids": ["F001"],
      "type": "режим"
    },
    {
